import { StrictMode } from "react";
import { createRoot } from "react-dom/client";

function App() {
  return null;
}

createRoot(document.getElementById("root")).render(
  <StrictMode>
    <App />
  </StrictMode>,
);

import { test, expect } from "@playwright/test";
import AxeBuilder from "@axe-core/playwright";

test.describe("Trail Runner 2 product page", () => {
  test("provides an accessible page skeleton", async ({ page }) => {
    await page.goto("/");

    await expect(page).toHaveTitle(/Stride/);
    await expect(page.getByRole("banner")).toContainText("Stride");
    await expect(page.getByRole("banner")).toContainText(/cart/i);
    await expect(page.getByRole("navigation", { name: /main/i })).toBeVisible();

    const results = await new AxeBuilder({ page })
      .withTags(["wcag2a", "wcag2aa", "wcag22aa"])
      .analyze();
    expect(results.violations).toEqual([]);
  });

  test("offers the store sections from the main menu", async ({ page }) => {
    await page.goto("/");

    const menu = page.getByRole("navigation", { name: /main/i });
    await expect(menu.getByRole("link", { name: /^men$/i })).toBeVisible();
    await expect(menu.getByRole("link", { name: /^women$/i })).toBeVisible();
    await expect(menu.getByRole("link", { name: /^kids$/i })).toBeVisible();

    await menu.getByRole("link", { name: /^women$/i }).focus();
    await page.keyboard.press("Enter");
    await expect(page).toHaveURL(/women/i);
  });

  test("renders a navigable breadcrumb path", async ({ page }) => {
    await page.goto("/");

    const breadcrumbs = page.getByRole("navigation", { name: /breadcrumb/i });
    await expect(breadcrumbs.getByRole("link", { name: /^shop$/i })).toBeVisible();
    await expect(breadcrumbs.getByRole("link", { name: /^trail$/i })).toBeVisible();
    await expect(
      breadcrumbs.getByText("Trail Runner 2", { exact: true }),
    ).toBeVisible();

    await breadcrumbs.getByRole("link", { name: /^trail$/i }).focus();
    await page.keyboard.press("Enter");
    await expect(page).toHaveURL(/trail/i);
  });

  test("shows one shoe photo and cycles previous and next with wraparound", async ({
    page,
  }) => {
    await page.goto("/");

    const photo = page.getByRole("img", { name: /Trail Runner 2/i });
    const next = page.getByRole("button", { name: /next photo/i });
    const previous = page.getByRole("button", { name: /previous photo/i });
    await expect(photo).toHaveCount(1);

    const firstPhoto = await photo.getAttribute("src");
    await next.click();
    await expect(photo).not.toHaveAttribute("src", firstPhoto);
    await previous.click();
    await expect(photo).toHaveAttribute("src", firstPhoto);

    await previous.click();
    const lastPhoto = await photo.getAttribute("src");
    await expect(photo).not.toHaveAttribute("src", firstPhoto);
    await next.click();
    await expect(photo).toHaveAttribute("src", firstPhoto);
    expect(lastPhoto).not.toBe(firstPhoto);
  });

  test("explains that the displayed price includes taxes", async ({ page }) => {
    await page.goto("/");

    await expect(page.getByText(/^\$\d/)).toBeVisible();
    const taxInfo = page.getByRole("button", { name: /taxes/i });
    await taxInfo.focus();
    await expect(page.getByRole("tooltip")).toBeVisible();
    await taxInfo.blur();
    await expect(page.getByRole("tooltip")).toBeHidden();
    await taxInfo.hover();
    await expect(page.getByRole("tooltip")).toBeVisible();
  });

  test("uses exclusive, keyboard-accessible color choices", async ({ page }) => {
    await page.goto("/");

    const colors = page.getByRole("radiogroup", { name: /color/i });
    const blue = colors.getByRole("radio", { name: /^blue$/i });
    const black = colors.getByRole("radio", { name: /^black$/i });
    const grey = colors.getByRole("radio", { name: /^grey$/i });
    await expect(colors.getByRole("radio")).toHaveCount(3);
    await expect(blue).toHaveAttribute("aria-checked", "true");
    await expect(black).toHaveAttribute("aria-checked", "false");
    await expect(grey).toHaveAttribute("aria-checked", "false");

    await blue.focus();
    await page.keyboard.press("ArrowRight");
    await expect(black).toHaveAttribute("aria-checked", "true");
    await expect(blue).toHaveAttribute("aria-checked", "false");
    await page.keyboard.press("ArrowRight");
    await expect(grey).toHaveAttribute("aria-checked", "true");
  });

  test("changes size through a closed-by-default control and disables sold-out sizes", async ({
    page,
  }) => {
    await page.goto("/");

    const size = page.getByRole("combobox", { name: /size/i });
    await expect(size).toBeVisible();
    await expect(size).toHaveValue("");
    await expect(size.locator("option:disabled")).toHaveCount(1);
    await expect(size.locator("option:disabled")).toContainText(/sold out/i);
    await size.selectOption({ label: "US 8" });
    await expect(size).toHaveValue("8");
  });

  test("opens a modal size guide, calculates a size, and restores focus on close", async ({
    page,
  }) => {
    await page.goto("/");

    const guideButton = page.getByRole("button", { name: /size guide/i });
    await guideButton.focus();
    await guideButton.press("Enter");

    const dialog = page.getByRole("dialog", { name: /size guide/i });
    await expect(dialog).toHaveAttribute("aria-modal", "true");
    await expect(dialog.getByRole("textbox", { name: /foot length/i })).toBeFocused();
    await expect(dialog.getByRole("radio", { name: /^us$/i })).toBeChecked();
    await expect(dialog.getByRole("radio", { name: /^eu$/i })).toBeVisible();

    await dialog.getByRole("textbox", { name: /foot length/i }).fill("25.5");
    await dialog.getByRole("radio", { name: /^eu$/i }).check();
    await expect(dialog.getByText(/your size/i)).toBeVisible();
    await page.keyboard.press("Escape");
    await expect(dialog).toBeHidden();
    await expect(guideButton).toBeFocused();
  });

  test("supports typed and one-step quantity changes", async ({ page }) => {
    await page.goto("/");

    const quantity = page.getByRole("spinbutton", { name: /quantity/i });
    await expect(quantity).toHaveValue("1");
    await page.getByRole("button", { name: /increase quantity/i }).click();
    await expect(quantity).toHaveValue("2");
    await page.getByRole("button", { name: /decrease quantity/i }).click();
    await expect(quantity).toHaveValue("1");
    await quantity.fill("4");
    await expect(quantity).toHaveValue("4");
  });

  test("requires a size before adding to cart and confirms a successful add", async ({
    page,
  }) => {
    await page.goto("/");

    const add = page.getByRole("button", { name: /add to cart/i });
    await add.click();
    await expect(page.getByRole("alert")).toContainText(/pick a size/i);

    await page.getByRole("combobox", { name: /size/i }).selectOption({ label: "US 8" });
    await add.click();
    await expect(page.getByRole("status")).toContainText(/added to cart/i);
  });

  test("toggles the wishlist heart with an announced pressed state", async ({ page }) => {
    await page.goto("/");

    const wishlist = page.getByRole("button", { name: /wishlist/i });
    await expect(wishlist).toHaveAttribute("aria-pressed", "false");
    await wishlist.focus();
    await page.keyboard.press("Enter");
    await expect(wishlist).toHaveAttribute("aria-pressed", "true");
    await page.keyboard.press("Enter");
    await expect(wishlist).toHaveAttribute("aria-pressed", "false");
  });

  test("switches between details, reviews, and shipping as APG tabs", async ({
    page,
  }) => {
    await page.goto("/");

    const tabs = page.getByRole("tablist", { name: /product information/i });
    const details = tabs.getByRole("tab", { name: /^details$/i });
    const reviews = tabs.getByRole("tab", { name: /^reviews$/i });
    const shipping = tabs.getByRole("tab", { name: /^shipping$/i });
    await expect(details).toHaveAttribute("aria-selected", "true");
    await expect(page.locator('[role="tabpanel"]:visible')).toHaveCount(1);

    await details.focus();
    await page.keyboard.press("ArrowRight");
    await expect(reviews).toHaveAttribute("aria-selected", "true");
    await expect(page.locator('[role="tabpanel"]:visible')).toContainText(/review/i);
    await shipping.click();
    await expect(shipping).toHaveAttribute("aria-selected", "true");
    await expect(page.locator('[role="tabpanel"]:visible')).toContainText(/shipping/i);
  });

  test("reveals each FAQ answer only when its disclosure is opened", async ({ page }) => {
    await page.goto("/");

    const faq = page.getByRole("region", { name: /questions|faq/i });
    const question = faq.getByRole("button").first();
    await expect(question).toHaveAttribute("aria-expanded", "false");
    await expect(faq.locator('[role="region"]:visible')).toHaveCount(0);
    await question.focus();
    await page.keyboard.press("Enter");
    await expect(question).toHaveAttribute("aria-expanded", "true");
    await expect(faq.locator('[role="region"]:visible')).toHaveCount(1);
    await page.keyboard.press("Enter");
    await expect(question).toHaveAttribute("aria-expanded", "false");
  });

  test("provides help, company, and social links in the footer", async ({ page }) => {
    await page.goto("/");

    const footer = page.getByRole("contentinfo");
    await expect(footer.getByRole("link", { name: /customer help/i })).toBeVisible();
    await expect(footer.getByRole("link", { name: /company/i })).toBeVisible();
    await expect(footer.getByRole("link", { name: /instagram|facebook|twitter|social/i })).toHaveCount(
      1,
    );
  });
});

