import { StrictMode } from "react";
import { createRoot } from "react-dom/client";
import { useEffect, useRef, useState } from "react";
import "./styles.css";

function App() {
  const photos = [
    "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 800 800'%3E%3Crect width='800' height='800' fill='%23e8f0f5'/%3E%3Cellipse cx='405' cy='600' rx='280' ry='44' fill='%23c9d5dc'/%3E%3Cpath d='M180 490c90-30 148-125 211-202 31-37 91-36 116 13l61 119c22 44 72 72 127 93 35 13 40 55 3 68-117 40-353 36-495 13-42-7-57-84-23-104z' fill='%232b75b5'/%3E%3Cpath d='M177 507c139 35 303 52 520 12 28 20 22 48-2 61-113 42-362 39-493 11-37-8-54-65-25-84z' fill='%231d2935'/%3E%3Cpath d='M402 299c39-29 84-25 106 11l43 84-75 22-107-59z' fill='%23f3f6f7'/%3E%3Cpath d='M380 341l128 68M364 368l124 62M351 397l112 54' stroke='%232b75b5' stroke-width='10'/%3E%3C/svg%3E",
    "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 800 800'%3E%3Crect width='800' height='800' fill='%23f4eee5'/%3E%3Cellipse cx='410' cy='603' rx='280' ry='42' fill='%23d8cec1'/%3E%3Cpath d='M177 491c98-32 157-150 227-209 34-29 79-15 101 28l58 112c23 43 71 74 132 97 30 12 32 48 0 61-126 43-362 36-496 12-39-7-53-83-22-101z' fill='%234c5962'/%3E%3Cpath d='M174 507c145 35 330 51 521 11 26 19 19 50-8 61-121 39-356 37-486 11-35-7-54-64-27-83z' fill='%23222b30'/%3E%3Cpath d='M424 305c38-27 76-16 96 22l46 79-79 20-104-62z' fill='%23edf0ed'/%3E%3Cpath d='M390 354l137 59M374 382l133 55M359 410l117 48' stroke='%234c5962' stroke-width='10'/%3E%3C/svg%3E",
  ];
  const [photoIndex, setPhotoIndex] = useState(0);
  const [color, setColor] = useState("Blue");
  const [size, setSize] = useState("");
  const [quantity, setQuantity] = useState(1);
  const [wishlist, setWishlist] = useState(false);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [message, setMessage] = useState("");
  const [activeTab, setActiveTab] = useState("details");
  const [openFaq, setOpenFaq] = useState(null);
  const guideButtonRef = useRef(null);
  const dialogInputRef = useRef(null);
  const colors = ["Blue", "Black", "Grey"];
  const tabs = ["details", "reviews", "shipping"];

  useEffect(() => {
    if (dialogOpen) dialogInputRef.current?.focus();
    else if (guideButtonRef.current) guideButtonRef.current.focus();
  }, [dialogOpen]);

  useEffect(() => {
    const close = (event) => event.key === "Escape" && setDialogOpen(false);
    if (dialogOpen) document.addEventListener("keydown", close);
    return () => document.removeEventListener("keydown", close);
  }, [dialogOpen]);

  const changeColor = (index) => setColor(colors[(index + colors.length) % colors.length]);

  return (
    <div className="site">
      <header className="topbar" role="banner">
        <a className="logo" href="/">Stride</a>
        <nav aria-label="Main navigation">
          <a href="/men">Men</a>
          <a href="/women">Women</a>
          <a href="/kids">Kids</a>
        </nav>
        <div className="header-actions">
          <a href="/search" aria-label="Search">⌕</a>
          <a href="/account" aria-label="Account">♙</a>
          <a href="/cart">Cart (0)</a>
        </div>
      </header>

      <main>
        <nav className="breadcrumbs" aria-label="Breadcrumb">
          <a href="/shop">Shop</a><span>/</span>
          <a href="/trail">Trail</a><span>/</span>
          <span aria-current="page">Trail Runner 2</span>
        </nav>

        <section className="product-grid" aria-labelledby="product-title">
          <div className="gallery">
            <div className="photo-frame">
              <img src={photos[photoIndex]} alt="Trail Runner 2 trail running shoe" />
              <button className="photo-button previous" onClick={() => setPhotoIndex((photoIndex - 1 + photos.length) % photos.length)} aria-label="Previous photo">←</button>
              <button className="photo-button next" onClick={() => setPhotoIndex((photoIndex + 1) % photos.length)} aria-label="Next photo">→</button>
            </div>
            <p className="photo-count">{photoIndex + 1} / {photos.length}</p>
          </div>

          <div className="product-details">
            <p className="eyebrow">New arrival · All-terrain performance</p>
            <div className="title-row">
              <div><h1 id="product-title">Trail Runner 2</h1><p className="subtitle">Built for the path ahead.</p></div>
              <button className="heart" aria-label="Wishlist" aria-pressed={wishlist} onClick={() => setWishlist(!wishlist)}>{wishlist ? "♥" : "♡"}</button>
            </div>
            <div className="price-row">
              <strong>$145</strong>
              <span className="tax-wrap">
                <button className="info-button" aria-label="Taxes included">i</button>
                <span role="tooltip" className="tooltip">Price includes taxes.</span>
              </span>
            </div>

            <fieldset className="color-group" role="radiogroup" aria-label="Color">
              <legend>Color <span>{color}</span></legend>
              <div className="swatches">
                {colors.map((item, index) => (
                  <button key={item} role="radio" aria-label={item} aria-checked={color === item} tabIndex={color === item ? 0 : -1}
                    className={`swatch ${item.toLowerCase()}`} onClick={() => setColor(item)}
                    onKeyDown={(event) => {
                      if (event.key === "ArrowRight" || event.key === "ArrowDown") { event.preventDefault(); changeColor(index + 1); }
                      if (event.key === "ArrowLeft" || event.key === "ArrowUp") { event.preventDefault(); changeColor(index - 1); }
                    }} />
                ))}
              </div>
            </fieldset>

            <div className="size-heading">
              <label htmlFor="size">Size</label>
              <button ref={guideButtonRef} className="text-button" onClick={() => setDialogOpen(true)}>Size guide</button>
            </div>
            <select id="size" aria-label="Size" value={size} onChange={(event) => setSize(event.target.value)}>
              <option value="">Select a size</option>
              <option value="7">US 7</option>
              <option value="8">US 8</option>
              <option value="9">US 9</option>
              <option value="10" disabled>US 10 — Sold out</option>
              <option value="11">US 11</option>
            </select>

            <div className="purchase-row">
              <div className="quantity">
                <label htmlFor="quantity">Quantity</label>
                <div className="quantity-control">
                  <button aria-label="Decrease quantity" onClick={() => setQuantity(Math.max(1, quantity - 1))}>−</button>
                  <input id="quantity" aria-label="Quantity" type="number" min="1" value={quantity} onChange={(event) => setQuantity(event.target.value)} />
                  <button aria-label="Increase quantity" onClick={() => setQuantity(Number(quantity || 0) + 1)}>+</button>
                </div>
              </div>
              <button className="add-button" onClick={() => size ? setMessage("Trail Runner 2 added to cart.") : setMessage("Please pick a size before adding to cart.")}>Add to cart</button>
            </div>
            {message && <p className={size ? "success" : "error"} role={size ? "status" : "alert"}>{message}</p>}
            <p className="shipping-note">Free shipping and returns on every order.</p>
          </div>
        </section>

        <section className="information" aria-labelledby="info-title">
          <h2 id="info-title" className="sr-only">Product information</h2>
          <div className="tablist" role="tablist" aria-label="Product information">
            {tabs.map((tab, index) => <button key={tab} role="tab" id={`tab-${tab}`} aria-controls={`panel-${tab}`} aria-selected={activeTab === tab} tabIndex={activeTab === tab ? 0 : -1}
              onClick={() => setActiveTab(tab)} onKeyDown={(event) => {
                if (event.key === "ArrowRight") { event.preventDefault(); setActiveTab(tabs[(index + 1) % tabs.length]); }
                if (event.key === "ArrowLeft") { event.preventDefault(); setActiveTab(tabs[(index - 1 + tabs.length) % tabs.length]); }
              }}>{tab[0].toUpperCase() + tab.slice(1)}</button>)}
          </div>
          {tabs.map((tab) => activeTab === tab && <div key={tab} role="tabpanel" id={`panel-${tab}`} aria-labelledby={`tab-${tab}`}>
            {tab === "details" && <><h3>Made for the miles beyond the map.</h3><p>Trail Runner 2 brings responsive cushioning, a grippy outsole, and a breathable upper to every adventure.</p></>}
            {tab === "reviews" && <><h3>Reviews</h3><p>Trail runners love the comfortable fit and confident grip. Rated 4.8 out of 5.</p></>}
            {tab === "shipping" && <><h3>Shipping</h3><p>Shipping is free, with easy returns within 30 days.</p></>}
          </div>)}
        </section>

        <section className="faq" aria-labelledby="faq-title" role="region">
          <h2 id="faq-title">Questions</h2>
          {["Is Trail Runner 2 waterproof?", "How does the fit run?", "Can I return my shoes?"].map((question, index) => {
            const id = question.replace(/\W/g, "-");
            const open = openFaq === index;
            return <div className="faq-item" key={question}>
              <button aria-expanded={open} aria-controls={`answer-${id}`} onClick={() => setOpenFaq(open ? null : index)}>{question}<span>{open ? "−" : "+"}</span></button>
              {open && <div id={`answer-${id}`} role="region" aria-label={`${question} answer`}><p>We designed Trail Runner 2 to keep you comfortable and confident on every trail.</p></div>}
            </div>;
          })}
        </section>
      </main>

      <footer role="contentinfo">
        <div><h2>Need a hand?</h2><a href="/help">Customer help</a><a href="/contact">Contact us</a></div>
        <div><h2>Stride</h2><a href="/company">Company</a><a href="/careers">Careers</a></div>
        <div><h2>Follow along</h2><a href="/social">Instagram</a></div>
        <p>© 2026 Stride. Go your own way.</p>
      </footer>

      {dialogOpen && <div className="modal-backdrop">
        <div className="dialog" role="dialog" aria-modal="true" aria-labelledby="size-guide-title">
          <button className="dialog-close" aria-label="Close size guide" onClick={() => setDialogOpen(false)}>×</button>
