  font-synthesis: none;
}
* { box-sizing: border-box; }
body { margin: 0; }
a { color: inherit; text-decoration: none; }
button, input, select { font: inherit; }
button, a, select, input { outline-color: #1c6ca8; outline-offset: 3px; }
.site { min-height: 100vh; }
.topbar { height: 80px; padding: 0 5vw; display: flex; align-items: center; gap: 56px; border-bottom: 1px solid #dce1df; background: #fff; }
.logo { font-size: 1.65rem; font-weight: 800; letter-spacing: -.08em; }
.topbar nav { display: flex; gap: 30px; font-size: .82rem; text-transform: uppercase; letter-spacing: .08em; }
.topbar nav a:hover, footer a:hover { text-decoration: underline; }
.header-actions { margin-left: auto; display: flex; align-items: center; gap: 20px; font-size: .82rem; }
.header-actions a:first-child, .header-actions a:nth-child(2) { font-size: 1.35rem; }
main { max-width: 1240px; margin: auto; padding: 28px 5vw 90px; }
.breadcrumbs { display: flex; gap: 12px; align-items: center; color: #59696f; font-size: .78rem; margin-bottom: 34px; }
.breadcrumbs a { color: #263e49; }
.breadcrumbs a:hover { text-decoration: underline; }
.product-grid { display: grid; grid-template-columns: minmax(0, 1.08fr) minmax(340px, .92fr); gap: clamp(40px, 7vw, 110px); }
.photo-frame { position: relative; background: #e8f0f5; }
.photo-frame img { display: block; width: 100%; aspect-ratio: 1 / 1; object-fit: cover; }
.photo-button { position: absolute; top: 50%; transform: translateY(-50%); border: 0; border-radius: 50%; width: 42px; height: 42px; background: #fff; color: #18242b; cursor: pointer; font-size: 1.25rem; }
.photo-button.previous { left: 18px; }
.photo-button.next { right: 18px; }
.photo-count { color: #59696f; font-size: .75rem; text-align: right; margin: 9px 2px; }
.eyebrow { color: #56666c; font-size: .72rem; letter-spacing: .1em; text-transform: uppercase; margin: 6px 0 16px; }
.title-row { display: flex; justify-content: space-between; align-items: start; }
h1 { font-size: clamp(2.5rem, 5vw, 4.5rem); letter-spacing: -.07em; line-height: .95; margin: 0; font-weight: 700; }
.subtitle { color: #657277; margin: 15px 0 34px; }
.heart { border: 1px solid #cbd4d2; background: #fff; border-radius: 50%; cursor: pointer; font-size: 1.65rem; line-height: 1; width: 46px; height: 46px; }
.price-row { display: flex; align-items: center; gap: 9px; margin-bottom: 35px; }
.price-row strong { font-size: 1.35rem; }
.info-button { border: 1px solid #839095; color: #485a61; border-radius: 50%; width: 18px; height: 18px; line-height: 15px; padding: 0; cursor: help; background: transparent; font-size: .7rem; font-weight: 700; }
.tax-wrap { position: relative; }
.tooltip { display: none; position: absolute; white-space: nowrap; left: 28px; top: -8px; background: #18242b; color: white; padding: 8px 11px; border-radius: 3px; font-size: .72rem; z-index: 2; }
.info-button:hover + .tooltip, .info-button:focus + .tooltip { display: block; }
.color-group { border: 0; padding: 0; margin: 0 0 29px; }
.color-group legend { font-size: .8rem; font-weight: 700; margin-bottom: 13px; }
.color-group legend span { font-weight: 400; color: #637078; margin-left: 8px; }
.swatches { display: flex; gap: 11px; }
.swatch { width: 28px; height: 28px; border-radius: 50%; border: 3px solid #fff; box-shadow: 0 0 0 1px #b8c1bf; cursor: pointer; }
.swatch[aria-checked="true"] { box-shadow: 0 0 0 2px #18242b; }
.swatch.blue { background: #2878b7; }.swatch.black { background: #1d2428; }.swatch.grey { background: #929a9b; }
.size-heading { display: flex; justify-content: space-between; align-items: center; margin-bottom: 9px; font-size: .8rem; font-weight: 700; }
.text-button { border: 0; border-bottom: 1px solid currentColor; background: transparent; cursor: pointer; font-size: .75rem; padding: 0; }
#size { width: 100%; border: 1px solid #b7c2c0; background: #fff; border-radius: 0; padding: 14px; color: #18242b; }
.purchase-row { display: flex; gap: 13px; align-items: end; margin-top: 22px; }
.quantity label { display: block; font-size: .75rem; font-weight: 700; margin-bottom: 9px; }
.quantity-control { display: flex; border: 1px solid #b7c2c0; background: #fff; }
.quantity-control button { width: 35px; border: 0; background: #fff; cursor: pointer; font-size: 1.1rem; }
.quantity-control input { width: 45px; text-align: center; border: 0; padding: 13px 2px; -moz-appearance: textfield; }
.quantity-control input::-webkit-inner-spin-button { appearance: none; }
.add-button { flex: 1; border: 0; background: #18242b; color: #fff; padding: 15px 20px; cursor: pointer; font-weight: 700; }
.add-button:hover { background: #2c5669; }
.error, .success { font-size: .8rem; margin: 16px 0 0; }.error { color: #a32626; }.success { color: #17683d; }
.shipping-note { color: #59696f; font-size: .75rem; margin-top: 24px; }
.information { border-top: 1px solid #cbd4d2; margin-top: 92px; }
.tablist { display: flex; gap: 38px; border-bottom: 1px solid #cbd4d2; }
.tablist button { border: 0; border-bottom: 2px solid transparent; background: transparent; padding: 20px 0 16px; cursor: pointer; text-transform: uppercase; letter-spacing: .1em; font-size: .7rem; }
.tablist button[aria-selected="true"] { border-color: #18242b; font-weight: 700; }
[role="tabpanel"] { max-width: 680px; padding: 30px 0; min-height: 150px; }
[role="tabpanel"] h3 { font-size: 1.25rem; margin: 0 0 12px; }.information p { color: #637078; line-height: 1.65; }
.faq { max-width: 850px; margin-top: 28px; }.faq h2 { font-size: 1.7rem; letter-spacing: -.04em; }
.faq-item { border-top: 1px solid #cbd4d2; }.faq-item:last-child { border-bottom: 1px solid #cbd4d2; }
.faq-item > button { width: 100%; display: flex; justify-content: space-between; padding: 19px 0; border: 0; background: transparent; cursor: pointer; text-align: left; font-weight: 700; }
.faq-item [role="region"] { padding: 0 0 17px; color: #637078; font-size: .9rem; }.faq-item [role="region"] p { margin: 0; }
footer { display: grid; grid-template-columns: repeat(3, 1fr); gap: 30px; background: #18242b; color: #fff; padding: 52px 5vw; }
footer h2 { font-size: .75rem; text-transform: uppercase; letter-spacing: .1em; color: #a8b9bd; margin: 0 0 18px; } footer a { display: block; font-size: .85rem; margin: 9px 0; }
footer p { grid-column: 1 / -1; color: #9cabad; font-size: .72rem; margin: 20px 0 0; }
.modal-backdrop { position: fixed; inset: 0; display: grid; place-items: center; background: rgb(12 22 26 / .58); z-index: 5; padding: 20px; }
.dialog { position: relative; width: min(470px, 100%); background: #fff; padding: 38px; box-shadow: 0 20px 70px rgb(0 0 0 / .25); }
.dialog h2 { margin: 0; font-size: 2rem; letter-spacing: -.05em; }.dialog > p { color: #637078; font-size: .9rem; }
.dialog > label { display: block; font-size: .78rem; font-weight: 700; margin-top: 28px; }.dialog > input { width: 100%; border: 1px solid #b7c2c0; padding: 13px; margin-top: 9px; }
.dialog-close { position: absolute; top: 14px; right: 16px; border: 0; background: transparent; font-size: 1.6rem; cursor: pointer; }
.unit-choice { display: flex; gap: 20px; border: 0; padding: 0; margin: 23px 0; font-size: .82rem; }.unit-choice legend { width: 100%; font-weight: 700; font-size: .78rem; margin-bottom: 10px; }.calculated { margin-bottom: 0; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
@media (max-width: 720px) {
  .topbar { height: auto; padding: 20px 5vw; flex-wrap: wrap; gap: 20px; }.topbar nav { order: 3; width: 100%; justify-content: space-between; }.header-actions { gap: 10px; }
  .product-grid { grid-template-columns: 1fr; }.product-details { max-width: 600px; }.information { margin-top: 55px; } footer { grid-template-columns: 1fr 1fr; }
}

